  children DEF T1 Transform {
    translation -1.5 0 0
    children Shape {
      appearance DEF AP1 Appearance {
        material Material {
          diffuseColor 0.5 0.5 0.5
        }
        shaders DEF CSA ComposedShader {
          language "GLSL"
          parts [
            DEF VA ShaderPart {
              url "data:x-shader/x-vertex,
attribute vec4 x3d_Vertex;
attribute vec3 x3d_Normal;
attribute vec4 x3d_TexCoord0;
attribute vec4 x3d_Color;
uniform mat4 x3d_ProjectionMatrix;
uniform mat4 x3d_ModelViewMatrix;
uniform mat3 x3d_NormalMatrix;
varying vec3 vN;
varying vec3 vP;
varying vec2 vT;
varying vec4 vC;
void main()
{
   vec4 p = x3d_ModelViewMatrix * x3d_Vertex;
   vP = p.xyz;
   vN = normalize (x3d_NormalMatrix * x3d_Normal);
   vT = x3d_TexCoord0.st;
   vC = x3d_Color;
   gl_Position = x3d_ProjectionMatrix * p;
}
"
            }
            DEF FA ShaderPart {
              type "FRAGMENT"
              url "data:x-shader/x-fragment,
precision mediump float;
varying vec3 vN;
varying vec3 vP;
varying vec2 vT;
varying vec4 vC;
void main() { gl_FragColor = vec4 (1.0, 0.3, 0.2, 1.0); }
"
            }
          ]
        }
      }
      geometry Sphere {
        radius 0.6
      }
    }
  }
}

Transform {
  translation 1.5 0 0
