      material Material {
        diffuseColor 0.2 0.3 0.8
      }
      shaders DEF CSB ComposedShader {
        language "GLSL"
        parts [
          USE VA
          DEF FB ShaderPart {
            type "FRAGMENT"
            url "data:x-shader/x-fragment,
